import { Chess, type Move } from 'chess.js';
import { dir, explanations, msg, tr, type LineText } from './i18n.ts';

// A repertoire is a set of lines (SAN, from the initial position).
// Lines are merged into a position-keyed book, so transpositions just work.
// `idea` is the plan of the line in one or two sentences; `notes` explain single moves,
// keyed by move label: "2.Bf4" for White, "4...Qb6" for Black (checked by scripts/check-lines.ts).
// Other languages: src/lang/repertoire.<id>.ts, by the id of the line. The id also keys the saved progress, so it
// stays when a line is renamed.

export type Line = {
  id: string; // unique in the repertoire, never changes
  name: string;
  moves: string;
  idea?: string;
  notes?: Record<string, string>;
  custom?: string; // a branch the user added from their games: the opponent's deviating move ("2.Bc4")
};

export type Repertoire = {
  id: string;
  name: string;
  userColor: 'w' | 'b';
  lines: Line[];
};

